JSONGenerator gen = JSON.createGenerator(false);
gen.writeStartObject();
gen.writeStringField('name', 'Acme');
gen.writeNumberField('n', 7);
gen.writeBooleanField('ok', true);
gen.writeNullField('missing');
gen.writeDateField('date', Date.newInstance(2024, 2, 29));
gen.writeDateTimeField('when', Datetime.newInstance(2024, 2, 29, 12, 34, 56));
gen.writeTimeField('clock', Time.newInstance(5, 6, 7, 0));
gen.writeIdField('id', Id.valueOf('001B000001DVM9t'));
gen.writeBlobField('blob', Blob.valueOf('abc'));
gen.writeFieldName('items');
gen.writeStartArray();
gen.writeString('x');
gen.writeNumber(2);
gen.writeBoolean(false);
gen.writeNull();
gen.writeEndArray();
gen.writeEndObject();
String text = gen.getAsString();
System.assert(text.contains('"name":"Acme"'));
System.assert(text.contains('"date":"2024-02-29"'));
System.assert(text.contains('"when":"2024-02-29T12:34:56Z"'));
System.assert(text.contains('"clock":"05:06:07"'));
System.assert(text.contains('"id":"001B000001DVM9t"'));
System.assert(text.contains('"blob":"YWJj"'));
System.assert(text.contains('"items":["x",2,false,null]'));
System.assert(gen.isClosed());
JSONGenerator pretty = JSON.createGenerator(true);
pretty.writeStartObject();
pretty.writeStringField('name', 'Acme');
pretty.writeBooleanField('ok', true);
pretty.writeEndObject();
String prettyText = pretty.getAsString();
System.assert(prettyText.contains('  "name": "Acme"'));
JSONParser parser = JSON.createParser(text);
System.assertEquals(JSONToken.START_OBJECT, parser.nextToken());
System.assertEquals(JSONToken.FIELD_NAME, parser.nextToken());
System.assertEquals('name', parser.getText());
System.assertEquals(JSONToken.VALUE_STRING, parser.nextValue());
System.assertEquals('Acme', parser.getText());
System.assertEquals(JSONToken.FIELD_NAME, parser.nextToken());
System.assertEquals(JSONToken.VALUE_NUMBER_INT, parser.nextValue());
System.assertEquals(7, parser.getIntegerValue());
System.assertEquals(JSONToken.FIELD_NAME, parser.nextToken());
System.assertEquals(JSONToken.VALUE_TRUE, parser.nextValue());
System.assertEquals(true, parser.getBooleanValue());
System.assertEquals(JSONToken.FIELD_NAME, parser.nextToken());
System.assertEquals(JSONToken.VALUE_NULL, parser.nextValue());
System.assertEquals(JSONToken.FIELD_NAME, parser.nextToken());
System.assertEquals(JSONToken.VALUE_STRING, parser.nextValue());
System.assertEquals(Date.newInstance(2024, 2, 29), parser.getDateValue());
System.assertEquals(JSONToken.FIELD_NAME, parser.nextToken());
System.assertEquals(JSONToken.VALUE_STRING, parser.nextValue());
System.assertEquals(Datetime.newInstance(2024, 2, 29, 12, 34, 56), parser.getDatetimeValue());
System.assertEquals(JSONToken.FIELD_NAME, parser.nextToken());
System.assertEquals(JSONToken.VALUE_STRING, parser.nextValue());
System.assertEquals(Time.newInstance(5, 6, 7, 0), parser.getTimeValue());
System.assertEquals(JSONToken.FIELD_NAME, parser.nextToken());
System.assertEquals(JSONToken.VALUE_STRING, parser.nextValue());
Id parsedId = parser.getIdValue();
System.assertEquals('001B000001DVM9t', parsedId.toString());
System.assertEquals('001B000001DVM9t', parsedId.to15());
System.assertEquals(JSONToken.FIELD_NAME, parser.nextToken());
System.assertEquals(JSONToken.VALUE_STRING, parser.nextValue());
Blob parsedBlob = parser.getBlobValue();
System.assertEquals('abc', parsedBlob.toString());
System.assertEquals(JSONToken.FIELD_NAME, parser.nextToken());
System.assertEquals(JSONToken.START_ARRAY, parser.nextValue());
parser.skipChildren();
System.assertEquals(JSONToken.END_ARRAY, parser.getCurrentToken());
System.assertEquals(JSONToken.END_OBJECT, parser.nextToken());
System.assertEquals(null, parser.nextToken());

JSONGenerator raw = JSON.createGenerator(false);
raw.writeStartObject();
raw.writeRawField('config', '{"enabled":true,"nums":[1,2]}');
raw.writeFieldName('items');
raw.writeStartArray();
raw.writeRawValue('{"raw":true}');
raw.writeRaw('[false,null]');
raw.writeEndArray();
raw.writeEndObject();
System.assertEquals('{"config":{"enabled":true,"nums":[1,2]},"items":[{"raw":true},[false,null]]}', raw.getAsString());
JSONParser numericParser = JSON.createParser('{"whole":12,"fraction":1.25}');
System.assertEquals(null, numericParser.getCurrentName());
System.assertEquals(JSONToken.START_OBJECT, numericParser.nextToken());
System.assertEquals(JSONToken.FIELD_NAME, numericParser.nextToken());
System.assertEquals('whole', numericParser.getCurrentName());
System.assertEquals(JSONToken.VALUE_NUMBER_INT, numericParser.nextValue());
System.assertEquals('whole', numericParser.getCurrentName());
System.assertEquals(12, numericParser.getLongValue());
numericParser.clearCurrentToken();
System.assertEquals(null, numericParser.getCurrentToken());
System.assertEquals(null, numericParser.getCurrentName());
System.assertEquals(JSONToken.FIELD_NAME, numericParser.nextToken());
System.assertEquals(JSONToken.VALUE_NUMBER_FLOAT, numericParser.nextValue());
System.assertEquals(1.25, numericParser.getDoubleValue());
System.assertEquals(1.25, numericParser.getDecimalValue());

Integer typedInt = JSON.deserialize('7', Integer.class);
System.assertEquals(7, typedInt);
Long typedLong = JSON.deserialize('9223372036854775807', Long.class);
System.assertEquals(9223372036854775807, typedLong);
Decimal typedDecimal = JSON.deserialize('1.25', Decimal.class);
System.assertEquals(1.25, typedDecimal);
Boolean typedBool = JSON.deserialize('true', Boolean.class);
System.assertEquals(true, typedBool);
String typedString = JSON.deserialize('"Acme"', String.class);
System.assertEquals('Acme', typedString);
Object typedNull = JSON.deserialize('null', String.class);
System.assertEquals(null, typedNull);
Date typedDate = JSON.deserialize('"2024-02-29"', Date.class);
System.assertEquals(Date.newInstance(2024, 2, 29), typedDate);
Datetime typedDatetime = JSON.deserialize('"2024-02-29T12:34:56Z"', Datetime.class);
System.assertEquals(Datetime.newInstance(2024, 2, 29, 12, 34, 56), typedDatetime);
Time typedTime = JSON.deserialize('"05:06:07"', Time.class);
System.assertEquals(Time.newInstance(5, 6, 7, 0), typedTime);
Id typedId = JSON.deserialize('"001B000001DVM9t"', Id.class);
System.assertEquals('001B000001DVM9t', typedId.toString());
Blob typedBlob = JSON.deserialize('"YWJj"', Blob.class);
System.assertEquals('abc', typedBlob.toString());
Type jsonListType = Type.forName('List<Integer>');
List<Integer> typedList = JSON.deserialize('[1,2,null]', jsonListType);
System.assertEquals(3, typedList.size());
System.assertEquals(2, typedList.get(1));
System.assertEquals(null, typedList.get(2));
Type jsonMapType = Type.forName('Map<String,Integer>');
Map<String,Integer> typedMap = JSON.deserialize('{"a":1,"b":null}', jsonMapType);
System.assertEquals(1, typedMap.get('a'));
System.assertEquals(null, typedMap.get('b'));
Object untypedEdge = JSON.deserializeUntyped('{"items":[1,null,2.5],"nested":{"ok":true},"missing":null}');
System.assertEquals(null, untypedEdge.get('missing'));
Object edgeItems = untypedEdge.get('items');
System.assertEquals(3, edgeItems.size());
System.assertEquals(2.5, edgeItems.get(2));
Object edgeNested = untypedEdge.get('nested');
System.assertEquals(true, edgeNested.get('ok'));
String compactNoNull = JSON.serialize(new Account(Name = 'NoNull', Phone = null), true);
System.assert(compactNoNull.contains('"Name":"NoNull"'));
System.assert(!compactNoNull.contains('Phone'));
String prettyNoNull = JSON.serializePretty(new Account(Name = 'PrettyNoNull', Phone = null), true);
System.assert(prettyNoNull.contains('  "Name": "PrettyNoNull"'));
System.assert(!prettyNoNull.contains('Phone'));
Map<String,Object> nestedSerialize = new Map<String,Object>();
nestedSerialize.put('kept', 'yes');
nestedSerialize.put('missing', null);
List<Object> nestedSerializeItems = new List<Object>();
nestedSerializeItems.add(nestedSerialize);
nestedSerializeItems.add(null);
Map<String,Object> nestedSerializeRoot = new Map<String,Object>();
nestedSerializeRoot.put('items', nestedSerializeItems);
String nestedCompact = JSON.serialize(nestedSerializeRoot, true);
System.assert(nestedCompact.contains('"items":[{'));
System.assert(nestedCompact.contains('"kept":"yes"'));
System.assert(nestedCompact.contains('"missing":null'));
System.assert(nestedCompact.contains('},null]'));
String nestedPretty = JSON.serializePretty(nestedSerializeRoot, true);
System.assert(nestedPretty.contains('  "items": ['));
System.assert(nestedPretty.contains('      "kept": "yes"'));
System.assert(nestedPretty.contains('      "missing": null'));
String compactWithNull = JSON.serialize(new Account(Name = 'WithNull', Phone = null), false);
System.assert(compactWithNull.contains('"Phone":null'));
JSONParser stateParser = JSON.createParser('{"outer":{"inner":1},"tail":2}');
System.assertEquals(JSONToken.START_OBJECT, stateParser.nextToken());
System.assertEquals(JSONToken.FIELD_NAME, stateParser.nextToken());
System.assertEquals('outer', stateParser.getCurrentName());
System.assertEquals(JSONToken.START_OBJECT, stateParser.nextValue());
stateParser.skipChildren();
System.assertEquals(JSONToken.END_OBJECT, stateParser.getCurrentToken());
System.assertEquals('outer', stateParser.getCurrentName());
stateParser.clearCurrentToken();
System.assertEquals(null, stateParser.getCurrentToken());
System.assertEquals(null, stateParser.getCurrentName());
System.assertEquals(JSONToken.FIELD_NAME, stateParser.nextToken());
System.assertEquals('tail', stateParser.getCurrentName());

